    /// `vtc/members/make-membership:applicationEntry`
    ///
    /// `subject`'s entry is of the `application` community role — a non-member holding resource grants. It becomes a membership through the join flow, or with vtc/members/admit, which keeps its grants.
    ///
    /// Declared `retryable: false`.
    pub const APPLICATION_ENTRY: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/members/make-membership:applicationEntry",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vtc/members/make-membership:entryNotLive`
    ///
